SELECT quantity_bucket, product_id, unique_products, min_quantity FROM (SELECT CASE WHEN quantity >= 232 THEN 'high' WHEN quantity >= 79 THEN 'mid' ELSE 'low' END AS quantity_bucket, product_id, COUNT(DISTINCT quantity) AS unique_products, MIN(quantity) AS min_quantity FROM inventory GROUP BY CASE WHEN quantity >= 232 THEN 'high' WHEN quantity >= 79 THEN 'mid' ELSE 'low' END, product_id) AS t WHERE unique_products > 7 ORDER BY quantity_bucket;
